import{_ as e,o,c as r,ag as n}from"./chunks/framework.BIas3y6W.js";const g=JSON.parse('{"title":"Week 7 Lab — Read It, Debug It","description":"","frontmatter":{"source":"weeks/07-read-and-debug/lab.md"},"headers":[],"relativePath":"weeks/07-read-and-debug/lab.md","filePath":"weeks/07-read-and-debug/lab.md"}'),a={name:"weeks/07-read-and-debug/lab.md"};function i(s,t,d,h,c,l){return o(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="week-7-lab--read-it-debug-it" tabindex="-1">Week 7 Lab — Read It, Debug It <a class="header-anchor" href="#week-7-lab--read-it-debug-it" aria-label="Permalink to &quot;Week 7 Lab — Read It, Debug It&quot;">​</a></h1><p><strong>AI-use key:</strong> 🟢 AI on: use AI freely · 🟡 AI limited: the AI may comment or hint, but the work is yours · 🔴 AI off: close the AI tabs and work alone.</p><p>In <strong>Studio A</strong> you read your own Project 1 code, find errors a partner plants in it, and set up the clinic. In <strong>Studio B</strong> you find and fix five planted bugs in someone else&#39;s app with the AI switched off: the <strong>Debug Clinic</strong>.</p><p><strong>You need:</strong> your Project 1 repository from week 6, a partner, and a GitHub account.</p><p>Using a screen reader or only a keyboard? See the <a href="./../../resources/accessibility.html">screen reader and keyboard guide</a>. Working alone? Each pair activity has a <strong>Working alone?</strong> line.</p><hr><h2 id="studio-a--read-it-75-min" tabindex="-1">Studio A — Read it (75 min) <a class="header-anchor" href="#studio-a--read-it-75-min" aria-label="Permalink to &quot;Studio A — Read it (75 min)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time</th><th>Part</th><th>AI use</th><th>Core or if time</th></tr></thead><tbody><tr><td>0:00–0:30</td><td>Recap, concept talk and live demo</td><td>—</td><td></td></tr><tr><td>0:30–0:45</td><td><a href="#part-a1--map-your-own-app-15-min">Part A1 — Map your own app</a></td><td>🔴 AI off</td><td>Core</td></tr><tr><td>0:45–0:55</td><td><a href="#part-a2--the-error-drill-10-min">Part A2 — The error drill</a></td><td>🔴 AI off</td><td>Core (breakpoints: if time)</td></tr><tr><td>0:55–1:05</td><td><a href="#part-a3--set-up-the-debug-clinic-10-min">Part A3 — Set up the Debug Clinic</a></td><td>🔴 AI off</td><td>Core</td></tr><tr><td>1:05–1:15</td><td>Exit ticket, graded on completion, not correctness</td><td>🔴 AI off</td><td></td></tr></tbody></table><h3 id="part-a1--map-your-own-app-15-min" tabindex="-1">Part A1 — Map your own app (15 min) <a class="header-anchor" href="#part-a1--map-your-own-app-15-min" aria-label="Permalink to &quot;Part A1 — Map your own app (15 min)&quot;">​</a></h3><p>🔴 <strong>AI off.</strong> This is practice for explaining your own code, one of the <a href="./../../resources/without-ai-skills.html#2-explain-any-function-you-committed">six skills you must show without AI</a>. Nobody marks your map.</p><p><strong>Why:</strong> you can&#39;t debug what you can&#39;t find. Every app in this course has the same five parts; today you find them in your own files.</p><ol><li><strong>Open your Project 1 Codespace.</strong> Go to <a href="https://github.com/codespaces" target="_blank" rel="noreferrer">github.com/codespaces</a> and open the one for your Project 1 repository (or, on the repository page, <strong>Code</strong> → <strong>Codespaces</strong> → <strong>Create codespace on main</strong>).</li><li><strong>Start the preview.</strong> In the terminal: <code>python3 -m http.server 8000</code>, then <strong>Open in Browser</strong>. In the new tab, open <strong><a href="./../../resources/glossary.html#devtools">DevTools</a></strong> (F12, or Ctrl+Shift+I; Cmd+Option+I on a Mac), click <strong>Console</strong>, reload, and note anything red or yellow.</li><li><strong>Fill in this map</strong> in your notes. Use <strong>Ctrl+F</strong> (Cmd+F) in the editor to search a file.</li></ol><table tabindex="0"><thead><tr><th>Part</th><th>Find it</th><th>Write down</th></tr></thead><tbody><tr><td><strong>Structure</strong></td><td>An element in <code>index.html</code> with an <code>id</code> that <code>app.js</code> uses</td><td>The id, and the line in each file</td></tr><tr><td><strong>Style</strong></td><td>One rule in <code>style.css</code></td><td>What it changes on the screen</td></tr><tr><td><strong>Behavior</strong></td><td>One <code>addEventListener</code> in <code>app.js</code>, and a <code>lib/</code> function it uses</td><td>Which element, which event, which function runs, and what the <code>lib/</code> rule decides</td></tr><tr><td><strong>State</strong></td><td>The variable that holds your list of items</td><td>Its name, and one line that changes it</td></tr><tr><td><strong>Storage</strong></td><td><code>localStorage.setItem</code> and <code>localStorage.getItem</code></td><td>The key name, the line that saves and the line that loads</td></tr></tbody></table><ol start="4"><li><strong>See your saved data.</strong> In DevTools, open <strong>Application</strong> (Chrome, Edge) or <strong>Storage</strong> (Firefox, Safari) → <strong>Local Storage</strong> → your site. Find your key and look at the saved text. It&#39;s <a href="./../../resources/glossary.html#json">JSON</a>: text that looks like a Python list of dicts, with double quotes.</li></ol><p>✅ <strong>Checkpoint:</strong> you can point at the line that saves your data and the line that loads it, and explain each in one sentence.</p><h3 id="part-a2--the-error-drill-10-min" tabindex="-1">Part A2 — The error drill (10 min) <a class="header-anchor" href="#part-a2--the-error-drill-10-min" aria-label="Permalink to &quot;Part A2 — The error drill (10 min)&quot;">​</a></h3><p>🔴 <strong>AI off.</strong> <strong>Why:</strong> finding the failing line from an error is the first of the <a href="./../../resources/without-ai-skills.html#1-read-an-error-message-and-find-the-failing-line">six skills you must show without AI</a>. Practice it now, with a partner, on your own code.</p><ol><li><strong>Commit first</strong> (Source Control → message <code>Before the error drill</code> → <strong>Commit</strong>), so you can always get back.</li><li><strong>Swap laptops.</strong> Your partner makes <strong>one</strong> small change to your <code>app.js</code> or <code>index.html</code> while you look away, saves, and hands it back. Pick from: <ul><li>misspell a variable at one place it&#39;s used (<code>items</code> → <code>itmes</code>);</li><li>change an element&#39;s <code>id</code> in <code>index.html</code> only;</li><li>delete one closing bracket <code>)</code> or <code>}</code>;</li><li>change the localStorage key in the load line only (hard: there&#39;s no error at all).</li></ul></li><li><strong>Find it with the method.</strong> Reload with the Console open. Read the error aloud: its <strong>type</strong>, its <strong>message</strong>, its <strong>file and line</strong>. Click the link. Say your hypothesis before you touch anything, then fix it by hand.</li><li><strong>Verify,</strong> then swap roles.</li></ol><p>If the page breaks and you can&#39;t find why, undo with <strong>Ctrl+Z</strong> in the file, or discard the change in <strong>Source Control</strong> (right-click the file → <strong>Discard Changes</strong>).</p><p><strong>Working alone?</strong> Make one change from the list yourself, close the file, wait a minute, then find it from the Console as if someone else had made it.</p><p><strong>If time: breakpoints.</strong> In DevTools → <strong>Sources</strong>, open your <code>app.js</code>, click a line number inside your draw function to set a <strong><a href="./../../resources/glossary.html#breakpoint">breakpoint</a></strong> (a place where the code pauses), and use the app. Step through with the arrow buttons and hover over variables to see their values.</p><p>✅ <strong>Checkpoint:</strong> you found a planted error from the Console message, said its type, file and line, and fixed it by hand.</p><h3 id="part-a3--set-up-the-debug-clinic-10-min" tabindex="-1">Part A3 — Set up the Debug Clinic (10 min) <a class="header-anchor" href="#part-a3--set-up-the-debug-clinic-10-min" aria-label="Permalink to &quot;Part A3 — Set up the Debug Clinic (10 min)&quot;">​</a></h3><p>🔴 <strong>AI off.</strong> Setting up now gives Studio B a full hour of hunting. Everyone sets up their own copy, so you&#39;re ready whoever you pair with.</p><p>The kit is a small <strong>Reading Log</strong> app with <strong>five planted bugs</strong>. <strong>Don&#39;t start hunting yet</strong>: set it up, check it, and stop.</p><ol><li><p><strong>Copy the kit into a new, empty repository</strong> named <code>debug-clinic</code>, following <a href="./../../setup/codespaces.html#start-a-project-from-a-starter">Start a project from a starter</a>. The starter is the <strong>Debug Clinic</strong> (the template is <code>vc101-debug-clinic</code>, unless your instructor publishes their own copy). Then open a <strong>new</strong> Codespace on that repository.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Never run the copy command in your Project 1 Codespace. It overwrites files with the same names, such as <code>index.html</code> and <code>app.js</code>. Check the repository name at the top of the Codespace window first.</p></div></li><li><p><strong>Check that the AI is off.</strong> The kit includes a settings file (<code>.vscode/settings.json</code>) that switches off Copilot in this workspace. To check, open <code>app.js</code>, go to an empty line, and type <code>function</code>. No grey &quot;ghost text&quot; should appear. If it does, follow <a href="./../../setup/codespaces.html#turn-copilot-off-for-ai-off-activities">Turn Copilot off for AI-off activities</a>. Don&#39;t open the Chat view.</p></li><li><p><strong>Run the app</strong> as in Part A1 (<code>python3 -m http.server 8000</code> → <strong>Open in Browser</strong>) and open the Console.</p></li><li><p><strong>Stop both codespaces</strong> (<a href="./../../setup/codespaces.html#stop-and-delete-codespaces">stop and delete codespaces</a>). Reopening the clinic one at the start of Studio B takes under a minute.</p></li></ol><p>✅ <strong>Checkpoint:</strong> the Reading Log opened in a browser tab and said &quot;Loading your books…&quot;, the Console showed a red error, and no AI suggestions appeared in the editor.</p><h3 id="exit-ticket-10-min" tabindex="-1">Exit ticket (10 min) <a class="header-anchor" href="#exit-ticket-10-min" aria-label="Permalink to &quot;Exit ticket (10 min)&quot;">​</a></h3><p>The week 7 exit ticket: 🔴 AI off, graded on completion, not correctness. It&#39;s at the end of Studio A this week because the clinic fills Studio B. One question asks about your week 5 spec, from memory.</p><p><strong>Before you leave Studio A:</strong></p><ul><li>☐ Your Project 1 notes have your app map.</li><li>☐ The <code>debug-clinic</code> repository exists, and you&#39;ve seen its red error.</li><li>☐ Both codespaces are stopped (<a href="https://github.com/codespaces" target="_blank" rel="noreferrer">github.com/codespaces</a>).</li></ul><hr><h2 id="studio-b--the-debug-clinic-75-min" tabindex="-1">Studio B — The Debug Clinic (75 min) <a class="header-anchor" href="#studio-b--the-debug-clinic-75-min" aria-label="Permalink to &quot;Studio B — The Debug Clinic (75 min)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time</th><th>Part</th><th>AI use</th><th>Core or if time</th></tr></thead><tbody><tr><td>0:00–0:05</td><td><a href="#part-b1--start-the-clinic-5-min">Part B1 — Start the clinic</a></td><td>🔴 AI off</td><td>Core</td></tr><tr><td>0:05–1:00</td><td><a href="#part-b2--the-hunt-55-min">Part B2 — The hunt</a></td><td>🔴 AI off (🟡 tutor mode after 10 minutes stuck)</td><td>Core</td></tr><tr><td>1:00–1:15</td><td><a href="#part-b3--debrief-15-min">Part B3 — Debrief</a></td><td>—</td><td>Core</td></tr></tbody></table><p>There&#39;s no show and tell this week: the clinic gets the time.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Feeling stuck without the AI is normal, and it&#39;s the point.</strong> The bounty points are for fun and don&#39;t count toward your grade; taking part does. Fixing bugs 1–3 is a good result, and the 10-minute rule means nobody stays stuck for long.</p></div><p><strong>Why:</strong> in Anthropic&#39;s study, debugging was where people who learned with AI fell furthest behind (<a href="https://www.anthropic.com/research/AI-assistance-coding-skills" target="_blank" rel="noreferrer">Anthropic, 2026</a>). The only way to build the skill is to practice without the AI doing it for you.</p><h3 id="part-b1--start-the-clinic-5-min" tabindex="-1">Part B1 — Start the clinic (5 min) <a class="header-anchor" href="#part-b1--start-the-clinic-5-min" aria-label="Permalink to &quot;Part B1 — Start the clinic (5 min)&quot;">​</a></h3><ol><li><strong>Pair up.</strong> The <strong>driver</strong> types. The <strong>navigator</strong> reads the code, asks &quot;why?&quot;, and keeps the notes. Swap after every bug. Work in one partner&#39;s <code>debug-clinic</code> Codespace.</li><li><strong>Reopen it</strong> at <a href="https://github.com/codespaces" target="_blank" rel="noreferrer">github.com/codespaces</a>, start the server, open the app and the Console. Type <code>function</code> on an empty line in <code>app.js</code> once more: still no grey text.</li><li><strong>Read the rules.</strong> Open the kit&#39;s <code>README.md</code> from the Explorer (right-click it → <strong>Open Preview</strong>) and read the rules, the scoring and the <strong>five bug reports</strong>. Each bug can be fixed by changing one or two lines.</li></ol><h3 id="part-b2--the-hunt-55-min" tabindex="-1">Part B2 — The hunt (55 min) <a class="header-anchor" href="#part-b2--the-hunt-55-min" aria-label="Permalink to &quot;Part B2 — The hunt (55 min)&quot;">​</a></h3><p>🔴 <strong>AI off.</strong> 🟡 Tutor mode only after 10 minutes stuck on one bug and three hint cards.</p><p>Work through the bug reports <strong>in order</strong>, using the debugging method for every bug:</p><table tabindex="0"><thead><tr><th>Step</th><th>Ask yourselves</th></tr></thead><tbody><tr><td><strong>Reproduce</strong></td><td>Can we make it happen on purpose, following the report&#39;s steps?</td></tr><tr><td><strong>Isolate</strong></td><td>What does the Console say? Which file, which line, which function?</td></tr><tr><td><strong>Hypothesize</strong></td><td>&quot;We think ___ is wrong, because ___.&quot; Say it out loud before touching the code</td></tr><tr><td><strong>Test</strong></td><td>Can we check that idea first? Type a variable name in the Console, or add a temporary <code>console.log(...)</code></td></tr><tr><td><strong>Fix</strong></td><td>What&#39;s the smallest change that fixes the <em>cause</em>?</td></tr><tr><td><strong>Verify</strong></td><td>Repeat the report&#39;s steps. Are the earlier bugs still fixed?</td></tr></tbody></table><p>After each fix:</p><ol><li>Write the claim in <code>BUGS.md</code> (the format is in the kit&#39;s README).</li><li><strong>Commit your fix.</strong> In <strong>Source Control</strong>, type a message such as <code>Fix bug 2: wrong id for the book list</code>, click <strong>Commit</strong> (choose <strong>Yes</strong> if it asks to stage all changes), then click <strong>Sync Changes</strong> to push it.</li></ol><p><strong>Stuck? The 10-minute rule:</strong></p><ol><li>Ten minutes on the same bug with no progress → read <strong>one</strong> hint from the kit&#39;s <code>hint-cards.md</code> (or ask your instructor for the printed card).</li><li>Still stuck after hint 3 → 🟡 <strong>tutor mode</strong>. Open your chat assistant in a new browser tab, paste the prompt from <a href="./../../resources/tutor-mode.html">tutor mode</a>, then describe the bug report, what you&#39;ve tried, the exact error message, and the function you&#39;re looking at. The tutor gives hints, not fixes. Note it in <code>BUGS.md</code>.</li></ol><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Don&#39;t paste the whole app into a normal AI chat and ask it to fix it. That skips exactly the practice this lab exists for, and a claim only counts if you can explain the cause in your own words.</p></div><p><strong>All five fixed?</strong> Ask your instructor for a <strong>bonus bug</strong>, or set a breakpoint in <code>render</code> and step through it once.</p><p>✅ <strong>Checkpoint:</strong> at least bugs 1–3 are fixed, claimed in <code>BUGS.md</code> and committed. Bugs 4 and 5 are great if you get there. The debrief goes through all five.</p><p>When time is called, finish your sentence in <code>BUGS.md</code>, commit, and click <strong>Sync Changes</strong>.</p><p><strong>Working alone?</strong> Be your own navigator: before you change any code, say each step of the method out loud, or type it into <code>BUGS.md</code>. Explaining to a rubber duck works better than it sounds.</p><h3 id="part-b3--debrief-15-min" tabindex="-1">Part B3 — Debrief (15 min) <a class="header-anchor" href="#part-b3--debrief-15-min" aria-label="Permalink to &quot;Part B3 — Debrief (15 min)&quot;">​</a></h3><p>Your instructor goes through the five bugs, about three minutes each. For each, a pair reads its <code>BUGS.md</code> claim aloud (the error message, the line, the cause in one sentence), the class sees the one-line fix, and someone shares a wrong fix they tried and why it didn&#39;t work.</p><p>Your job: compare each cause with yours. Under each claim in <code>BUGS.md</code>, add one line: <strong>&quot;Next time I&#39;d check first: …&quot;</strong>. Then commit, <strong>Sync Changes</strong>, and stop the clinic Codespace. You won&#39;t need it again.</p><p>The clinic&#39;s five bugs are the most common bugs in beginner apps, AI-written or not. In the homework you look for them in your own Project 1.</p><p><strong>Before you leave Studio B:</strong></p><ul><li>☐ The <code>debug-clinic</code> repository is pushed, with a claim for every bug you fixed.</li><li>☐ <strong>Stop your codespace:</strong> <a href="https://github.com/codespaces" target="_blank" rel="noreferrer">github.com/codespaces</a> → <strong>…</strong> → <strong>Stop codespace</strong>. Stopped codespaces don&#39;t use your free hours.</li><li>☐ Homework: <a href="./homework.html">homework</a>. The first task is done with the AI off.</li></ul><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>Try this</th></tr></thead><tbody><tr><td>The codespace won&#39;t start, or says you&#39;re out of hours</td><td>Stop any other codespaces at <a href="https://github.com/codespaces" target="_blank" rel="noreferrer">github.com/codespaces</a>, then see <a href="./../../setup/codespaces.html">GitHub Codespaces</a>. Meanwhile, pair with your partner in their codespace</td></tr><tr><td>No &quot;Open in Browser&quot; pop-up</td><td>Open the <strong>Ports</strong> tab next to the terminal and click the globe icon next to port 8000. Pop-up blockers can stop the new tab too</td></tr><tr><td><code>Address already in use</code> when starting the server</td><td>A server is already running. Find the terminal running it and press Ctrl+C, or use another port: <code>python3 -m http.server 8001</code></td></tr><tr><td>&quot;Open in Browser&quot; shows an old version</td><td>Save the file (a dot on the tab means unsaved), then hard-reload with Ctrl+Shift+R (Cmd+Shift+R)</td></tr><tr><td>The page shows a list of files, or &quot;404&quot;</td><td>The server was started in the wrong folder. It shows the folder it was started in, and <code>index.html</code> must be in that folder</td></tr><tr><td>The Reading Log appeared inside my Project 1</td><td>The copy ran in the wrong Codespace and overwrote your files. If you haven&#39;t committed, run <code>git restore .</code> in the Project 1 terminal: it brings back the files git already tracks. Then delete the kit&#39;s extra files (<code>hint-cards.md</code>, <code>.vscode</code>) by hand. If you already committed, run <code>git revert HEAD --no-edit</code></td></tr><tr><td>Grey suggestions still appear in the clinic</td><td>The workspace settings didn&#39;t apply. Follow <a href="./../../setup/codespaces.html#turn-copilot-off-for-ai-off-activities">Turn Copilot off for AI-off activities</a>, and untick the setting again after the clinic</td></tr><tr><td>Bug 5 seems &quot;still broken&quot; after a correct fix</td><td>Old broken data is still saved. Add a book, or type <code>localStorage.clear()</code> in the Console, then reload</td></tr><tr><td><code>git push</code> or <strong>Sync Changes</strong> is rejected</td><td>Someone (maybe you, on github.com) changed the repository. Run <code>git pull</code>, then push again. Ask for help if you see &quot;conflict&quot;</td></tr></tbody></table>',61)])])}const u=e(a,[["render",i]]);export{g as __pageData,u as default};
